export class Sound {
 constructor(settings){this.settings=settings;this.context=null;this.musicTimer=null;this.voice=null;this.voiceId=null;this.step=0;}
 init(){try{this.context??=new(window.AudioContext||window.webkitAudioContext)();this.context.resume();if(!this.musicTimer)this.musicTimer=setInterval(()=>this.music(),420);}catch{}}
 tone(f,d=.12,type='sine',level=.1,slide){if(!this.context||this.settings.master===0)return;const t=this.context.currentTime,o=this.context.createOscillator(),g=this.context.createGain();o.type=type;o.frequency.setValueAtTime(f,t);if(slide)o.frequency.exponentialRampToValueAtTime(slide,t+d);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(Math.max(.0002,level*this.settings.master),t+.01);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g);g.connect(this.context.destination);o.start();o.stop(t+d+.01);}
 fx(kind){this.init();if(kind==='send'){this.tone(440,.1,'triangle',.09,880);setTimeout(()=>this.tone(660,.12,'sine',.07),100);}else if(kind==='success'){[392,494,587].forEach((f,i)=>setTimeout(()=>this.tone(f,.22,'triangle',.06),i*100));}else if(kind==='fail'){this.tone(180,.3,'sawtooth',.04,60);}else if(kind==='skill'){this.tone(260,.3,'triangle',.09,1200);}else if(kind==='turn'){this.tone(120,.06,'triangle',.045);}else if(kind==='paper'){this.tone(95,.11,'sawtooth',.025,240);}else this.tone(550,.055,'sine',.045);}
 music(){if(!this.context||!this.settings.music||!this.settings.master||document.hidden)return;const mix=this.settings.music*(this.voice&&!this.voice.paused&&!this.voice.ended ? .28 : 1);const bass=[65.41,65.41,77.78,58.27,65.41,65.41,87.31,58.27];const i=this.step++%16;this.tone(bass[Math.floor(i/2)],.27,'triangle',.045*mix);if(i%4===0)this.tone(110,.09,'sine',.065*mix,36);if(i%2)this.tone([261.63,311.13,349.23,233.08][Math.floor(i/4)],.12,'sine',.015*mix);}
 play(id,{onend,onmeta}={}){this.stopVoice();if(!this.settings.voice||!this.settings.master){onend?.();return null;}const a=new Audio(globalThis.ABSTRACT_ASSETS?.['audio/'+id]||`./assets/audio/${id}.mp3`);a.id='voice-track';a.hidden=true;a.setAttribute('aria-hidden','true');document.body.append(a);this.voice=a;this.voiceId=id;a.volume=Math.min(1,this.settings.voice*this.settings.master);a.onloadedmetadata=()=>onmeta?.(a.duration);a.onended=()=>onend?.();a.onerror=()=>onend?.();a.play().catch(()=>onend?.());return a;}
 stopVoice(){if(this.voice){this.voice.pause();this.voice.onended=null;this.voice.onerror=null;this.voice.remove();this.voice=null;}this.voiceId=null;}
 update(){if(this.voice)this.voice.volume=Math.min(1,this.settings.voice*this.settings.master);}
 destroy(){this.stopVoice();clearInterval(this.musicTimer);this.context?.close();}
}
